from concurrent.futures import ThreadPoolExecutor

requests = [
    {"url": "/v3/invoices", "method": "POST", "body": {"amount": 4200}},
    {"url": "/v3/invoices", "method": "POST", "body": {"amount": 1500}},
]

def send_one(req):
    return client.send(**req, retry_backoff_ms=500)

with ThreadPoolExecutor(max_workers=4) as pool:
    responses = list(pool.map(send_one, requests))

for r in responses:
    print(r.status_code)
